package io.github.diodeme.ji.provider.http;

import java.time.Clock;
import java.time.Duration;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.Optional;

public final class RetryAfter {
    private RetryAfter() {}

    public static Optional<Duration> parse(String value, Clock clock) {
        if (value == null || value.isBlank()) return Optional.empty();
        try {
            double seconds = Double.parseDouble(value.trim());
            return Optional.of(Duration.ofMillis(Math.max(0, Math.round(seconds * 1000))));
        } catch (NumberFormatException ignored) {
            try {
                Duration duration = Duration.between(clock.instant(), ZonedDateTime.parse(
                        value.trim(), DateTimeFormatter.RFC_1123_DATE_TIME).toInstant());
                return Optional.of(duration.isNegative() ? Duration.ZERO : duration);
            } catch (DateTimeParseException invalidDate) {
                return Optional.empty();
            }
        }
    }
}
